import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { Database } from '@/lib/supabase/types'

const AddToPOSchema = z.object({
  item_ids: z.array(z.string().uuid()).min(1).max(50),
})

export async function POST(request: NextRequest) {
  const ip = getClientIp(request)
  const { success } = await apiRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return gate

  const body = AddToPOSchema.safeParse(await request.json())
  if (!body.success) {
    return Response.json({ error: body.error.flatten() }, { status: 400 })
  }

  const { item_ids } = body.data

  // Verify every item_id belongs to this studio — fast IN query, single round-trip.
  const { data: ownedItems, error: ownershipError } = await supabase
    .from('inventory_items')
    .select('id')
    .eq('studio_id', member.studio_id)
    .in('id', item_ids)

  if (ownershipError) {
    logger.error({ err: ownershipError }, 'add-to-po: ownership check failed')
    return Response.json({ error: 'Failed to verify item ownership' }, { status: 500 })
  }

  const ownedIds = new Set((ownedItems ?? []).map((r) => r.id))
  const unauthorized = item_ids.find((id) => !ownedIds.has(id))
  if (unauthorized) {
    logger.warn(
      { item_id: unauthorized, studio_id: member.studio_id },
      'add-to-po: item does not belong to studio',
    )
    return new Response('Forbidden: one or more items do not belong to your studio', { status: 403 })
  }

  // RPC call — types come from generated Database['public']['Functions']['create_po_from_alerts']
  const rpcArgs: Database['public']['Functions']['create_po_from_alerts']['Args'] = {
    p_studio_id: member.studio_id,
    p_item_ids: item_ids,
  }

  const { data: poIds, error: rpcError } = await supabase.rpc('create_po_from_alerts', rpcArgs)

  if (rpcError) {
    logger.error({ err: rpcError, studio_id: member.studio_id }, 'add-to-po: RPC failed')
    return Response.json({ error: 'Failed to create purchase orders' }, { status: 500 })
  }

  return Response.json({ po_ids: poIds ?? [] }, { status: 200 })
}

import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { Database } from '@/lib/supabase/types'

const BulkThresholdsSchema = z.union([
  z.object({
    updates: z
      .array(
        z.object({
          item_id: z.string().uuid(),
          min_threshold: z.number().int().min(1),
        }),
      )
      .min(1)
      .max(500),
  }),
  z.object({ use_defaults: z.literal(true) }),
])

export async function PATCH(request: NextRequest) {
  const ip = getClientIp(request)
  const { success } = await apiRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })

  // Role check at API layer — fast rejection before hitting feature gate or RPC.
  // RPC enforces this too (SECURITY DEFINER), but API-layer check returns 403 immediately.
  if (!['owner', 'admin'].includes(member.role)) {
    return new Response('Forbidden: requires owner or admin role', { status: 403 })
  }

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return gate

  const body = BulkThresholdsSchema.safeParse(await request.json())
  if (!body.success) {
    return Response.json({ error: body.error.flatten() }, { status: 400 })
  }

  // RPC call — types come from generated Database['public']['Functions']['bulk_set_min_thresholds']
  const rpcArgs: Database['public']['Functions']['bulk_set_min_thresholds']['Args'] = {
    p_studio_id: member.studio_id,
    p_payload: body.data as Database['public']['Functions']['bulk_set_min_thresholds']['Args']['p_payload'],
  }

  const { data: updated, error: rpcError } = await supabase.rpc(
    'bulk_set_min_thresholds',
    rpcArgs,
  )

  if (rpcError) {
    logger.error(
      { err: rpcError, studio_id: member.studio_id },
      'bulk-thresholds: RPC failed',
    )
    return Response.json({ error: 'Failed to update thresholds' }, { status: 500 })
  }

  return Response.json({ updated: updated ?? 0 }, { status: 200 })
}

