import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import type { PlanTier } from '@/lib/billing/feature-gate'

// ─── Shared sub-type for the enriched alert row returned by GET ───────────────
// `suggested_qty` is computed server-side: GREATEST((min_threshold * 2) - current_stock, 1)
type AlertRow = {
  id: string
  studio_id: string
  item_id: string
  alert_type: string
  current_stock: number
  threshold: number
  acknowledged_at: string | null
  acknowledged_by: string | null
  created_at: string
  updated_at: string
  inventory_items: {
    id: string
    name: string
    sku: string | null
    current_stock: number
    min_threshold: number
    cost_per_unit_cents: number | null
    supplier_id: string | null
    supplier_name: string | null
  } | null
  suggested_qty: number
}

type AlertState = 'all_clear' | 'cant_fire' | 'has_alerts'

const AcknowledgeSchema = z.object({
  id: z.string().uuid(),
  notes: z.string().max(500).optional().nullable(),
})

export async function GET(request: NextRequest) {
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return gate

  const url = new URL(request.url)
  const open_only = url.searchParams.get('open') !== 'false'

  // Parallel: alerts + enriched item join, and no-min count — single DB round-trip each.
  let alertQuery = supabase
    .from('stock_alerts')
    .select(
      `
      id, studio_id, item_id, alert_type, current_stock, threshold,
      acknowledged_at, acknowledged_by, created_at, updated_at,
      inventory_items (
        id, name, sku, current_stock, min_threshold,
        cost_per_unit_cents, supplier_id,
        suppliers ( name )
      )
    `,
    )
    .eq('studio_id', member.studio_id)
    .order('created_at', { ascending: false })

  if (open_only) alertQuery = alertQuery.is('acknowledged_at', null)

  const [alertsResult, noMinResult] = await Promise.all([
    alertQuery,
    supabase
      .from('inventory_items')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', member.studio_id)
      .eq('min_threshold', 0)
      .eq('is_active', true),
  ])

  if (alertsResult.error) {
    logger.error({ err: alertsResult.error }, 'stock alerts GET failed')
    return Response.json({ error: 'Failed to fetch stock alerts' }, { status: 500 })
  }

  if (noMinResult.error) {
    logger.error({ err: noMinResult.error }, 'stock alerts no-min count failed')
    return Response.json({ error: 'Failed to fetch no-min count' }, { status: 500 })
  }

  const items_with_no_min = noMinResult.count ?? 0

  // Shape the enriched rows — compute suggested_qty server-side.
  const alerts: AlertRow[] = (alertsResult.data ?? []).map((row) => {
    const item = row.inventory_items as
      | {
          id: string
          name: string
          sku: string | null
          current_stock: number
          min_threshold: number
          cost_per_unit_cents: number | null
          supplier_id: string | null
          suppliers: { name: string } | null
        }
      | null

    const min_threshold = item?.min_threshold ?? row.threshold
    const current = item?.current_stock ?? row.current_stock
    const suggested_qty = Math.max(min_threshold * 2 - current, 1)

    return {
      id: row.id,
      studio_id: row.studio_id,
      item_id: row.item_id,
      alert_type: row.alert_type,
      current_stock: row.current_stock,
      threshold: row.threshold,
      acknowledged_at: row.acknowledged_at,
      acknowledged_by: row.acknowledged_by,
      created_at: row.created_at,
      updated_at: row.updated_at,
      inventory_items: item
        ? {
            id: item.id,
            name: item.name,
            sku: item.sku,
            current_stock: item.current_stock,
            min_threshold: item.min_threshold,
            cost_per_unit_cents: item.cost_per_unit_cents,
            supplier_id: item.supplier_id,
            supplier_name: item.suppliers?.name ?? null,
          }
        : null,
      suggested_qty,
    }
  })

  // Derive top-level state.
  let state: AlertState
  if (alerts.length > 0) {
    state = 'has_alerts'
  } else if (items_with_no_min > 0) {
    state = 'cant_fire'
  } else {
    state = 'all_clear'
  }

  return Response.json({ data: alerts, state, items_with_no_min })
}

const { data, error } = await supabase
